/**
 * MPV Video Player - Main Process Module
 *
 * 注意：此模組現在僅提供共享類型定義。
 * MpvVideoElement 現在直接在 Renderer 進程中運行，
 * 不再需要 Main 進程的 IPC 服務。
 *
 * 使用前提：
 * - Electron 設定 nodeIntegration: true
 * - Electron 設定 contextIsolation: false
 *
 * @example
 * ```typescript
 * // main.ts
 * import { app, BrowserWindow } from 'electron';
 *
 * app.whenReady().then(() => {
 *     const mainWindow = new BrowserWindow({
 *         webPreferences: {
 *             nodeIntegration: true,
 *             contextIsolation: false,
 *         },
 *     });
 *
 *     mainWindow.loadFile('index.html');
 * });
 * ```
 */

// 類型定義（供參考）
export type {
    VideoState,
    FrameData,
    FrameMetadata,
    VideoEvent,
    VideoMetadata,
    HdrInfo,
    FileSupportResult,
    TargetResolution,
    ThumbnailData,
} from './types';
